/**
 * @name Command injection in subprocess calls
 * @description Checking for command injection via subprocess calls
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs
import semmle.python.Concepts

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      (
        // subprocess module calls with shell=True risks
        call = API::moduleImport("subprocess").getMember(["call", "check_call", "check_output", "run", "Popen"]).getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name Command injection in click package
 * @description Check for user-controlled data flowing into subprocess calls
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection-click
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module ClickCommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      call = API::moduleImport("subprocess").getMember(["call", "check_call", "check_output", "run", "Popen"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module ClickCommandInjectionFlow = TaintTracking::Global<ClickCommandInjectionConfig>;
import ClickCommandInjectionFlow::PathGraph

from ClickCommandInjectionFlow::PathNode source, ClickCommandInjectionFlow::PathNode sink
where ClickCommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential command injection: user input flows into subprocess command at $@.", source.getNode(), "user input"
